INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(54548, 0, 0, 'Heroes, we have the Dragon Soul. The Aspects await us within Wyrmrest. Hurry -  come with me!', 12, 0, 100, 1, 0, 25870, 'THRALL_INTRO_1'),
(54548, 1, 0, 'How did they find us? Ready your weapons - we\'ve got to get out of this canyon!', 12, 0, 100, 1, 0, 25871, 'THRALL_INTRO_2'),
(54548, 2, 0, 'What magic is this?', 12, 0, 100, 1, 0, 25872, 'THRALL_INTRO_3'),
(54548, 3, 0, 'Look out!', 12, 0, 100, 1, 0, 25873, 'THRALL_INTRO_4'),
(54548, 4, 0, 'Take a moment to catch your breath before we move on.', 12, 0, 100, 1, 0, 25876, 'THRALL_INTRO_5');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(54590, 0, 0, 'You\'re a mere mortal. It is time you died like one.', 14, 0, 100, 0, 0, 25804, 'arcurion SAY_AGGRO'),
(54590, 1, 0, 'Nothing! Nothing....', 12, 0, 100, 0, 0, 25797, 'arcurion SAY_DEATH'),
(54590, 2, 0, 'The Hour of Twilight falls - the end of all things - you cannot stop it. You are nothing. NOTHING!', 14, 0, 100, 0, 0, 25801, 'arcurion SAY_PHASE'),
(54590, 3, 0, 'Mere mortals.', 14, 0, 100, 0, 0, 25803, 'arcurion SAY_KILL 1'),
(54590, 3, 1, 'Your Shaman can\'t protect you.', 14, 0, 100, 0, 0, 25805, 'arcurion SAY_KILL 2'),
(54590, 3, 2, 'The Aspects misplaced their trust.', 14, 0, 100, 0, 0, 25806, 'arcurion SAY_KILL 3'),
(54590, 4, 0, 'Enough, Shaman!', 14, 0, 100, 0, 0, 25807, 'arcurion SAY_TOMB 1'),
(54590, 4, 1, 'None will survive!', 14, 0, 100, 0, 0, 25808, 'arcurion SAY_TOMB 2'),
(54590, 4, 2, 'The Shaman is mine, focus on his companions!', 14, 0, 100, 0, 0, 25809, 'arcurion SAY_TOMB 3'),
(54590, 4, 3, 'Freeze!', 14, 0, 100, 0, 0, 25810, 'arcurion SAY_TOMB 4'),
(54590, 5, 0, 'Shaman! The Dragon Soul is not yours. Give it up, and you may yet walk away with your life.', 14, 0, 100, 0, 0, 25798, 'arcurion EVENT'),
(54590, 6, 0, 'Destroy them all, but bring the Shaman to me!', 14, 0, 100, 0, 0, 25799, 'arcurion EVENT'),
(54590, 7, 0, 'You will go nowhere, Shaman.', 14, 0, 100, 0, 0, 25800, 'arcurion EVENT'),
(54590, 8, 0, 'You\'re a fool if you think to take your place as the Aspect of Earth, Shaman!', 14, 0, 100, 0, 0, 25802, 'arcurion EVENT');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(54938, 0, 0, 'I looked into the eyes of The Dragon, and despaired...', 14, 0, 100, 0, 0, 25865, 'benedictus death'),
(54938, 1, 0, 'Get inside, quickly! I\'ll hold them off!', 12, 0, 100, 0, 0, 25866, 'benedictus event 01'),
(54938, 2, 0, 'And now, Shaman, you will give the Dragon Soul to ME.', 12, 0, 100, 0, 0, 25867, 'benedictus event 02'),
(54938, 3, 0, 'The Light will consume you!', 14, 0, 100, 0, 0, 25868, 'benedictus spell 01'),
(54938, 4, 0, 'Drown in Shadow!', 14, 0, 100, 0, 0, 25869, 'benedictus spell 02');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(54968, 0, 0, 'Let\'s get to work, shall we?', 14, 0, 100, 0, 0, 25816, 'asira aggro'),
(54968, 1, 0, 'You\'re much... better... than I thought...', 14, 0, 100, 0, 0, 25817, 'asira death'),
(54968, 2, 0, 'Where do you think you\'re going, little lizard?', 14, 0, 100, 0, 0, 25818, 'asira event 01'),
(54968, 3, 0, '...and with that out of the way, you and your flock of fumbling friends are next on my list. Mmm, I thought you\'d never get here!', 14, 0, 100, 0, 0, 25819, 'asira event 02'),
(54968, 4, 0, 'Ah. Well. That was even easier than I thought!', 14, 0, 100, 0, 0, 25820, 'asira event 03'),
(54968, 5, 0, 'Tch!  So soon?', 14, 0, 100, 0, 0, 25821, 'asira slay 01'),
(54968, 5, 1, 'I hope your friends can do better.', 14, 0, 100, 0, 0, 25822, 'asira slay 02'),
(54968, 5, 2, 'Mmm, too much fun!', 14, 0, 100, 0, 0, 25823, 'asira slay 03'),
(54968, 5, 3, 'Good night...', 14, 0, 100, 0, 0, 25824, 'asira slay 04'),
(54968, 6, 0, 'Bye-bye.', 14, 0, 100, 0, 0, 25825, 'asira spell 01'),
(54968, 6, 1, 'Now you see me...', 14, 0, 100, 0, 0, 25826, 'asira spell 02'),
(54968, 6, 2, 'Surprise.', 14, 0, 100, 0, 0, 25827, 'asira spell 03');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(54971, 0, 0, 'I will NOT, Archbishop. It will never be yours.', 12, 0, 100, 0, 0, 25893, 'THRALL_BENEDICTUS_1'),
(54971, 1, 0, 'You were a figurehead of the Light, Benedictus. How could you betray your own people?', 12, 0, 100, 0, 0, 25894, 'THRALL_BENEDICTUS_2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(54972, 0, 0, 'Beware. Enemies approach!', 14, 0, 100, 0, 0, 25883, 'THRALL_ASIRA_1'),
(54972, 1, 0, 'Let none stand in our way.', 14, 0, 100, 0, 0, 25884, 'THRALL_ASIRA_2'),
(54972, 2, 0, 'The Twilight\'s Hammer returns.', 14, 0, 100, 0, 0, 25885, 'THRALL_ASIRA_3'),
(54972, 3, 0, 'Let them come!', 14, 0, 100, 0, 0, 25886, 'THRALL_ASIRA_4'),
(54972, 4, 0, 'Alexstrasza\'s drakes should meet us here...', 12, 0, 100, 0, 0, 25887, 'THRALL_ASIRA_5'),
(54972, 5, 0, 'Up there, above us!', 12, 0, 100, 0, 0, 25888, 'THRALL_ASIRA_6'),
(54972, 6, 0, 'I haven\'t come to be stopped by the likes of you.', 14, 0, 100, 0, 0, 25890, 'THRALL_ASIRA_7'),
(54972, 7, 0, 'Well done, Let us see to our friend...', 12, 0, 100, 0, 0, 25891, 'THRALL_ASIRA_8'),
(54972, 8, 0, 'The rest of the drakes should be here shortly. I\'ll fly on ahead; catch up when you can.', 12, 0, 100, 0, 0, 25892, 'THRALL_ASIRA_9');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55107, 0, 0, 'Death to all who oppose us!', 14, 0, 100, 0, 0, 0, 'TWILIGHT_RANGER');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55636, 0, 0, 'Death to all who oppose us!', 14, 0, 100, 0, 0, 0, 'TWILIGHT_DRAKE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55779, 0, 0, 'Show yourself!', 12, 0, 100, 1, 0, 25877, 'THRALL_ARCURION_1'),
(55779, 1, 0, 'We\'re surrounded - dispatch the ascendant while I keep the ambushers at bay.', 14, 0, 100, 1, 0, 25878, 'THRALL_ARCURION_2'),
(55779, 2, 0, 'You\'ve almost got him! Og\'nor ka Lok\'tar - Now we finish this!', 14, 0, 100, 1, 0, 25881, 'THRALL_ARCURION_3'),
(55779, 3, 0, 'We\'ve been discovered. I know you\'re tired, but we cannot keep the Aspects waiting!', 12, 0, 100, 1, 0, 25882, 'THRALL_ARCURION_4'),
(55779, 4, 0, 'Follow me.', 12, 0, 100, 0, 0, 0, 'THRALL_ARCURION_5');
